// SPDX-License-Identifier: AGPL-3.0-or-later
// Phantom FX 22 DOORWAY: convolution through morphing spaces. The convolution is FFTConvolver's TwoStageFFTConvolver (HiFi-LoFi, MIT;
// zero latency: a 256-sample head and a 4096-sample tail partition). The spaces (impulse responses) are generated by us from the controls:
// five shapes (METALLIC, ORGANIC, HOLLOW, DIFFUSE, CRYSTALLINE), each with early reflections and a frequency-dependent decaying tail.
// Morph (the brief's "written on top"): WEIGHTED blends the IRs themselves, SPECTRAL blends their magnitude spectra frame by frame,
// CROSSFADE runs two IRs side by side and crossfades the outputs live. Rebuilding an IR allocates, so it happens on this unit's own
// worker thread into a spare convolver set; the audio thread only crossfades (60 ms) to a set once it is ready. Nothing waits on a lock.
#pragma once
#include "SpaceCommon.h"
#include "TwoStageFFTConvolver.h"
#include <atomic>
#include <random>

namespace phantom
{
class DoorwayFx final : public CatalogEffect
{
public:
    DoorwayFx() : CatalogEffect (uPortal) {}
    ~DoorwayFx() override { worker.reset(); }
    bool wetOnly() const override { return true; }
    bool widensOnPurpose() const override { return true; }
    double tailSeconds() const override { return 32.0; }

    struct Spec   // everything an IR set depends on, quantised so small knob jitter does not rebuild
    {
        int shape = 1, mode = 0; float size = 0.6f, density = 0.7f, decay = 4.0f, morph = 0.0f, tone = 0.0f, early = 0.5f, stretch = 1.0f;
        bool operator== (const Spec& o) const { return shape == o.shape && mode == o.mode && size == o.size && density == o.density && decay == o.decay && morph == o.morph && tone == o.tone && early == o.early && stretch == o.stretch; }
    };
protected:
    void prepareEffect (double sampleRate, int maxBlockSize, int) override
    {
        worker.reset();
        for (auto& s : sets) { s.state.store (kFree); s.built = Spec(); s.hasB = false; s.used = false; }
        staleMute = false;
        pre.prepare (sampleRate, 0.26);
        pSize = id ("size"); pShape = id ("shape"); pMove = id ("move"); pDens = id ("density"); pDecay = id ("decay"); pTrans = id ("transform");
        pFreeze = id ("freeze"); pPre = id ("predelay"); pTone = id ("tone"); pEarly = id ("early"); pMorph = id ("morph"); pStretch = id ("stretch");
        scratch.setSize (8, juce::jmax (maxBlockSize, 1024)); fbBuf.setSize (2, juce::jmax (maxBlockSize, 1024)); fbBuf.clear(); fadeBuf.setSize (2, juce::jmax (maxBlockSize, 1024));
        // the first set is built here (prepare thread), so the unit sounds from its first block
        Spec s0 = specFromTargets (0.0f); build (sets[0], s0); sets[0].state.store (kLive); cur = 0; next = -1; xf = 1.0f;
        movePhase = 0.0; drift = 0.0f; driftTarget = 0.0f; rng.seed (99);
        requested = s0; reqGen.store (0); worker = std::make_unique<Worker> (*this);
    }
    // message thread (before playback / on a topology change): what the IR depends on is rebuilt here at once, into the live set
    void updateParameters (const ModulationContext& ctx) override
    {
        EffectBase::updateParameters (ctx);
        Spec want = specFromTargets (0.0f); if (choice (pMorph) == 1) want.morph = std::floor (target (pTrans) * 4.0f);
        if (! (want == sets[(size_t) cur].built) && next < 0 && ! sets[(size_t) cur].used) { build (sets[(size_t) cur], want); requested = want; }
    }
    void resetEffect() override
    {
        // audio thread (a waking unit). FFTConvolver can only clear its history by re-initialising (which allocates), so a set that has
        // played is muted and the worker builds a fresh copy; the unit is silent until it arrives (tens of ms), never replaying old audio
        if (sets[(size_t) cur].used || (next >= 0 && sets[(size_t) next].used)) { staleMute = true; reqGen.fetch_add (1); }
        pre.reset(); glidePre.cur = -1.0f; fbBuf.clear(); movePhase = 0.0;
    }
public:
    void process (juce::dsp::AudioBlock<float> block, const ModulationContext& ctx) noexcept override
    {
        beginBlock (ctx);
        const int n = (int) block.getNumSamples(); auto* L = block.getChannelPointer (0); auto* R = block.getNumChannels() > 1 ? block.getChannelPointer (1) : L;
        for (auto* s : { &p (pSize), &p (pDens), &p (pDecay), &p (pTrans), &p (pTone), &p (pEarly), &p (pStretch) }) s->skip (n);
        // movement: STATIC, DRIFT (a slow random walk of the morph), ROTATE (cycles through the shapes), EXPAND (the room breathes in size)
        const int mv = choice (pMove); const double secs = n / sr; float moveMorph = 0.0f, moveSize = 0.0f;
        movePhase += secs; if (movePhase > 1.0e6) movePhase = 0.0;
        if (mv == 1) { if (std::abs (drift - driftTarget) < 0.01f) driftTarget = std::uniform_real_distribution<float> (-0.35f, 0.35f) (rng); drift += (driftTarget > drift ? 1.0f : -1.0f) * (float) secs * 0.04f; moveMorph = drift; }
        else if (mv == 2) moveMorph = (float) std::fmod (movePhase * 0.05, 1.0) * 5.0f;
        else if (mv == 3) moveSize = 0.25f * (float) std::sin (movePhase * 0.25 * juce::MathConstants<double>::twoPi);
        const float liveMorph = p (pTrans).current * 4.0f + moveMorph;
        // ask the worker for a new set when what the IR depends on has moved (it polls; no signalling from here)
        Spec want = specFromTargets (moveSize); want.morph = choice (pMorph) == 1 ? 0.0f : quant (liveMorph, 0.05f);
        if (choice (pMorph) == 1) want.morph = std::floor (liveMorph);   // CROSSFADE: the set holds the two shapes either side; the blend is live
        if (! (want == requested)) { requested = want; reqGen.fetch_add (1); }
        // a ready set: crossfade to it
        if (next < 0) for (int k = 0; k < kSets; ++k) if (sets[(size_t) k].state.load() == kReady) { sets[(size_t) k].state.store (kIncoming); next = k; xf = 0.0f; inFade = 0.0f; break; }
        const bool frozen = on (pFreeze);
        // input: pre-delayed, or (frozen) the wet fed back so the space holds
        float* inL = scratch.getWritePointer (0); float* inR = scratch.getWritePointer (1);
        for (int i = 0; i < n; ++i)
        {
            const float pd = glidePre (p (pPre).next() * 0.001f * (float) sr);
            pre.write (0, L[i]); pre.write (1, R[i]);
            inL[i] = frozen ? softLimit (fbBuf.getSample (0, i) * 0.98f) : pre.read (0, pd + 1.0f);
            inR[i] = frozen ? softLimit (fbBuf.getSample (1, i) * 0.98f) : pre.read (1, pd + 1.0f);
        }
        float* oL = scratch.getWritePointer (2); float* oR = scratch.getWritePointer (3);
        runSet (sets[(size_t) cur], inL, inR, oL, oR, n, liveMorph); sets[(size_t) cur].used = true;
        if (staleMute) for (int i = 0; i < n; ++i) { oL[i] = 0.0f; oR[i] = 0.0f; }
        if (next >= 0)
        {
            float* nL = scratch.getWritePointer (4); float* nR = scratch.getWritePointer (5);
            // its input fades in over 20 ms (a tone switched on mid-wave would click inside the fresh convolver)
            float* fL = fadeBuf.getWritePointer (0); float* fR = fadeBuf.getWritePointer (1);
            for (int i = 0; i < n; ++i) { inFade = juce::jmin (1.0f, inFade + 1.0f / (0.02f * (float) sr)); const float g = 0.5f - 0.5f * std::cos (inFade * juce::MathConstants<float>::pi); fL[i] = inL[i] * g; fR[i] = inR[i] * g; }
            runSet (sets[(size_t) next], fL, fR, nL, nR, n, liveMorph); sets[(size_t) next].used = true;
            const float step = 1.0f / (float) (0.06 * sr);
            for (int i = 0; i < n; ++i) { xf = juce::jmin (1.0f, xf + step); const float a = std::cos (xf * juce::MathConstants<float>::halfPi), b = std::sin (xf * juce::MathConstants<float>::halfPi); oL[i] = oL[i] * a + nL[i] * b; oR[i] = oR[i] * a + nR[i] * b; }
            if (xf >= 1.0f) { sets[(size_t) cur].state.store (kFree); cur = next; next = -1; sets[(size_t) cur].state.store (kLive); staleMute = false; }
        }
        for (int i = 0; i < n; ++i) { fbBuf.setSample (0, i, oL[i]); fbBuf.setSample (1, i, oR[i]); L[i] = oL[i] * kLevel; R[i] = oR[i] * kLevel; }
    }

private:
    static constexpr int kSets = 3, kFree = 0, kBuilding = 1, kReady = 2, kIncoming = 3, kLive = 4;
    static constexpr float kLevel = 0.658f;   // level match on pink noise
    static inline float softLimit (float x) noexcept { return x / (1.0f + std::abs (x)); }
    static float quant (float v, float q) noexcept { return std::round (v / q) * q; }
    struct Set
    {
        std::array<fftconvolver::TwoStageFFTConvolver, 4> conv;   // A left, A right, B left, B right (B only in CROSSFADE)
        std::atomic<int> state { 0 }; Spec built; bool hasB = false; bool used = false;
    };
    void runSet (Set& s, const float* inL, const float* inR, float* oL, float* oR, int n, float liveMorph) noexcept
    {
        s.conv[0].process (inL, oL, (size_t) n); s.conv[1].process (inR, oR, (size_t) n);
        if (s.hasB)
        {
            float* bL = scratch.getWritePointer (6); float* bR = scratch.getWritePointer (7);
            s.conv[2].process (inL, bL, (size_t) n); s.conv[3].process (inR, bR, (size_t) n);
            const float f = juce::jlimit (0.0f, 1.0f, liveMorph - s.built.morph);
            for (int i = 0; i < n; ++i) { cfm += (f - cfm) * cfCoeff; const float a = std::cos (cfm * juce::MathConstants<float>::halfPi), b = std::sin (cfm * juce::MathConstants<float>::halfPi); oL[i] = oL[i] * a + bL[i] * b; oR[i] = oR[i] * a + bR[i] * b; }
        }
    }
    Spec specFromTargets (float moveSize) const noexcept
    {
        Spec s; s.shape = choice (pShape); s.mode = choice (pMorph);
        s.size = quant (juce::jlimit (0.0f, 1.0f, target (pSize) + moveSize), 0.02f); s.density = quant (target (pDens), 0.02f);
        s.decay = quant (std::log (juce::jmax (0.3f, target (pDecay))), 0.03f); s.tone = quant (target (pTone), 0.04f); s.early = quant (target (pEarly), 0.04f);
        s.stretch = quant (target (pStretch), 0.02f); s.morph = quant (target (pTrans) * 4.0f, 0.05f);
        return s;
    }

    // ---------------------------------------------------------------- IR generation (worker / prepare thread; allocates)
    struct IR { std::vector<float> l, r; };
    IR makeShape (int shape, const Spec& sp) const
    {
        const double fs = sr; const double decay = std::exp ((double) sp.decay) * sp.stretch;
        const double sizeT = (0.4 + 1.6 * sp.size) * sp.stretch;   // time scale of the early pattern and the onset
        const int len = (int) (juce::jlimit (0.3, 20.0, decay * 1.25 + 0.1 * sizeT) * fs);
        IR ir; ir.l.assign ((size_t) len, 0.0f); ir.r.assign ((size_t) len, 0.0f);
        std::mt19937 g (1234u + (unsigned) shape * 77u); std::normal_distribution<float> nd (0.0f, 1.0f); std::uniform_real_distribution<float> ud (0.0f, 1.0f);
        // per shape: high-frequency decay (relative), brightness, density bias, resonances
        static const float hfDecay[] { 0.9f, 0.45f, 0.6f, 0.75f, 1.25f }, bright[] { 0.2f, -0.3f, -0.1f, 0.1f, 0.5f }, densBias[] { 0.0f, 0.1f, -0.3f, 0.4f, -0.4f };
        const int sh = juce::jlimit (0, 4, shape);
        const double dens = juce::jlimit (0.0, 1.0, (double) sp.density + densBias[sh]);
        const double rate = 300.0 + dens * dens * 6000.0;   // impulses / s at the start of the tail (it fills in over time)
        const double onset = 0.006 + 0.03 * sizeT;
        // three-band decay: a one-pole split of each noise source, each band with its own RT60
        const double rtLo = decay * 1.15, rtMid = decay, rtHi = decay * hfDecay[sh] * (1.0 + 0.3 * sp.tone);
        const float cLo = (float) std::exp (-2.0 * juce::MathConstants<double>::pi * 300.0 / fs), cHi = (float) std::exp (-2.0 * juce::MathConstants<double>::pi * 3500.0 / fs);
        float lpA[2] {}, lpB[2] {};
        for (int c = 0; c < 2; ++c)
        {
            auto& out = c == 0 ? ir.l : ir.r;
            for (int i = 0; i < len; ++i)
            {
                const double t = i / fs; if (t < onset * 0.3) continue;
                const double fill = juce::jmin (1.0, (t - onset * 0.3) / (onset * 2.0 + 0.05));   // echo density builds up
                const double pr = rate * (0.3 + 0.7 * fill) / fs;
                float x = (dens > 0.85 ? nd (g) * 0.35f : 0.0f);
                if (ud (g) < pr) x += (ud (g) < 0.5f ? -1.0f : 1.0f) * (float) std::sqrt (1.0 / juce::jmax (1.0e-9, pr)) * 0.35f;
                lpA[c] += (1.0f - cLo) * (x - lpA[c]); lpB[c] += (1.0f - cHi) * (x - lpB[c]);
                const float lo = lpA[c], mid = lpB[c] - lpA[c], hi = x - lpB[c];
                const auto env = [t] (double rt) { return (float) std::pow (10.0, -3.0 * t / rt); };
                const float ramp = (float) juce::jmin (1.0, (t - onset * 0.3) / (onset + 1.0e-3));
                out[(size_t) i] = ramp * (lo * env (rtLo) + mid * env (rtMid) + hi * env (rtHi) * (float) std::pow (2.0, (double) bright[sh] + sp.tone));
            }
        }
        // shape colour: METALLIC rings (inharmonic resonators), HOLLOW has a few broad tube resonances
        if (sh == 0 || sh == 2)
        {
            const int nr = sh == 0 ? 6 : 3; static const float fm[] { 1.0f, 1.59f, 2.14f, 2.65f, 3.16f, 3.65f }, fh[] { 1.0f, 2.3f, 5.0f };
            const float base = sh == 0 ? (float) (520.0 / (0.6 + sp.size)) : (float) (260.0 / (0.6 + sp.size));
            for (int c = 0; c < 2; ++c)
            {
                auto& out = c == 0 ? ir.l : ir.r; std::vector<float> res ((size_t) len, 0.0f);
                for (int k = 0; k < nr; ++k)
                {
                    const double f0 = base * (sh == 0 ? fm[k] : fh[k]) * (c == 0 ? 1.0 : 1.013), q = sh == 0 ? 60.0 : 4.0;
                    juce::dsp::IIR::Coefficients<float>::Ptr cf = juce::dsp::IIR::Coefficients<float>::makeBandPass (fs, juce::jmin (f0, fs * 0.45), q);
                    juce::dsp::IIR::Filter<float> f; f.coefficients = cf; f.reset();
                    for (int i = 0; i < len; ++i) res[(size_t) i] += f.processSample (out[(size_t) i]) * (sh == 0 ? 2.2f : 0.9f);
                }
                const float keep = sh == 0 ? 0.45f : 0.6f;
                for (int i = 0; i < len; ++i) out[(size_t) i] = out[(size_t) i] * keep + res[(size_t) i];
            }
        }
        // stereo: a shared and a difference part, so the two sides are related (a mono sum never cancels) but wide
        for (int i = 0; i < len; ++i) { const float a = ir.l[(size_t) i], b = ir.r[(size_t) i]; ir.l[(size_t) i] = 0.93f * a + 0.37f * b; ir.r[(size_t) i] = 0.93f * a - 0.37f * b; }
        // early reflections: 12 taps over the room's first ~(10..90) ms, louder for HOLLOW
        {
            std::mt19937 ge (555u + (unsigned) sh); std::uniform_real_distribution<float> u (0.0f, 1.0f);
            const float erGain = sp.early * (sh == 2 ? 1.6f : 1.0f);
            for (int k = 0; k < 12; ++k)
            {
                const double t = (0.004 + 0.085 * sizeT * (k + u (ge)) / 12.0); const int at = (int) (t * fs); if (at >= len) break;
                const float gk = erGain * 0.55f * (float) std::pow (0.82, k) * (u (ge) < 0.5f ? -1.0f : 1.0f), pan = u (ge) * 0.8f - 0.4f;
                ir.l[(size_t) at] += gk * (1.0f - pan); ir.r[(size_t) at] += gk * (1.0f + pan);
            }
        }
        // fade the last 10 %, then unit energy (white noise in keeps its level)
        const int fade = len / 10; for (int i = 0; i < fade; ++i) { const float w = (float) i / fade; ir.l[(size_t) (len - 1 - i)] *= w; ir.r[(size_t) (len - 1 - i)] *= w; }
        normalise (ir);
        return ir;
    }
    static void normalise (IR& ir)
    {
        double e = 0; for (size_t i = 0; i < ir.l.size(); ++i) e += 0.5 * ((double) ir.l[i] * ir.l[i] + (double) ir.r[i] * ir.r[i]);
        const float g = (float) (1.0 / std::sqrt (juce::jmax (1.0e-12, e))); for (size_t i = 0; i < ir.l.size(); ++i) { ir.l[i] *= g; ir.r[i] *= g; }
    }
    static IR blendWeighted (const IR& a, const IR& b, float f)
    {
        IR o; const size_t n = juce::jmax (a.l.size(), b.l.size()); o.l.assign (n, 0.0f); o.r.assign (n, 0.0f);
        for (size_t i = 0; i < n; ++i) { const float al = i < a.l.size() ? a.l[i] : 0.0f, ar = i < a.r.size() ? a.r[i] : 0.0f, bl = i < b.l.size() ? b.l[i] : 0.0f, br = i < b.r.size() ? b.r[i] : 0.0f;
            o.l[i] = al * (1.0f - f) + bl * f; o.r[i] = ar * (1.0f - f) + br * f; }
        normalise (o); return o;
    }
    // magnitude spectra blended frame by frame (2048-point Hann frames, 50 % overlap-add), the phase of the nearer IR
    static IR blendSpectral (const IR& a, const IR& b, float f)
    {
        const int order = 11, N = 1 << order, H = N / 2; juce::dsp::FFT fft (order);
        const size_t n = juce::jmax (a.l.size(), b.l.size()); IR o; o.l.assign (n + (size_t) N, 0.0f); o.r.assign (n + (size_t) N, 0.0f);
        std::vector<float> w ((size_t) N); for (int i = 0; i < N; ++i) w[(size_t) i] = 0.5f - 0.5f * std::cos (2.0f * juce::MathConstants<float>::pi * i / N);   // periodic Hann: sums to 1 at 50 %
        std::vector<std::complex<float>> A ((size_t) N), B ((size_t) N), ta ((size_t) N), tb ((size_t) N);
        for (int c = 0; c < 2; ++c)
        {
            const auto& xa = c == 0 ? a.l : a.r; const auto& xb = c == 0 ? b.l : b.r; auto& y = c == 0 ? o.l : o.r;
            for (size_t st = 0; st < n; st += (size_t) H)
            {
                for (int i = 0; i < N; ++i) { const size_t k = st + (size_t) i; ta[(size_t) i] = { k < xa.size() ? xa[k] * w[(size_t) i] : 0.0f, 0.0f }; tb[(size_t) i] = { k < xb.size() ? xb[k] * w[(size_t) i] : 0.0f, 0.0f }; }
                fft.perform (ta.data(), A.data(), false); fft.perform (tb.data(), B.data(), false);
                for (int k = 0; k < N; ++k) { const float m = std::abs (A[(size_t) k]) * (1.0f - f) + std::abs (B[(size_t) k]) * f; const float ph = std::arg (f < 0.5f ? A[(size_t) k] : B[(size_t) k]); A[(size_t) k] = std::polar (m, ph); }
                fft.perform (A.data(), ta.data(), true);
                for (int i = 0; i < N; ++i) y[st + (size_t) i] += ta[(size_t) i].real();
            }
        }
        o.l.resize (n); o.r.resize (n); normalise (o); return o;
    }
    void build (Set& s, const Spec& sp)
    {
        const int a = (int) std::floor (sp.mode == 1 ? sp.morph : sp.morph);
        const float f = sp.morph - (float) a;
        const int sa = ((sp.shape + a) % 5 + 5) % 5, sb = (sa + 1) % 5;
        IR irA = makeShape (sa, sp), irB;
        if (sp.mode == 1) irB = makeShape (sb, sp);
        else if (f > 0.001f) { IR other = makeShape (sb, sp); irA = sp.mode == 2 ? blendSpectral (irA, other, f) : blendWeighted (irA, other, f); }
        s.conv[0].init (256, 4096, irA.l.data(), irA.l.size()); s.conv[1].init (256, 4096, irA.r.data(), irA.r.size());
        s.hasB = sp.mode == 1;
        if (s.hasB) { s.conv[2].init (256, 4096, irB.l.data(), irB.l.size()); s.conv[3].init (256, 4096, irB.r.data(), irB.r.size()); }
        s.built = sp; s.used = false;
    }
    struct Worker : juce::Thread
    {
        explicit Worker (DoorwayFx& o) : juce::Thread ("Phantom FX DOORWAY IR builder"), owner (o) { startThread (juce::Thread::Priority::low); }
        ~Worker() override { stopThread (4000); }
        void run() override
        {
            int doneGen = owner.reqGen.load();
            while (! threadShouldExit())
            {
                wait (20);
                const int g = owner.reqGen.load(); if (g == doneGen) continue;
                // a free set (never the live, incoming or a ready one)
                int k = -1; for (int i = 0; i < kSets; ++i) { int expected = kFree; if (owner.sets[(size_t) i].state.compare_exchange_strong (expected, kBuilding)) { k = i; break; } }
                if (k < 0) continue;
                // the request is read without a lock: it is plain values, and a torn read only means one more rebuild at the next poll
                const Spec sp = owner.requested; doneGen = g;
                owner.build (owner.sets[(size_t) k], sp);
                owner.sets[(size_t) k].state.store (kReady);
                // wait until the audio thread has taken it before building another (keeps at most one set ahead)
                while (! threadShouldExit() && owner.sets[(size_t) k].state.load() == kReady) wait (5);
            }
        }
        DoorwayFx& owner;
    };

    std::array<Set, kSets> sets; int cur = 0, next = -1; float xf = 1.0f, cfm = 0.0f, cfCoeff = 0.002f;
    Spec requested; std::atomic<int> reqGen { 0 }; bool staleMute = false; float inFade = 1.0f; juce::AudioBuffer<float> fadeBuf;
    std::unique_ptr<Worker> worker;
    StereoDelay pre; PreGlide glidePre; juce::AudioBuffer<float> scratch, fbBuf;
    double movePhase = 0.0; float drift = 0.0f, driftTarget = 0.0f; std::minstd_rand rng;
    int pSize = 0, pShape = 0, pMove = 0, pDens = 0, pDecay = 0, pTrans = 0, pFreeze = 0, pPre = 0, pTone = 0, pEarly = 0, pMorph = 0, pStretch = 0;
};
} // namespace phantom
